def calculate_discount(price, user_type, is_member, years_active):
    discounts = {
        'student': {'base': 0.2, 'member': 0.25, 'loyal': 0.3},
        'senior': {'base': 0.15, 'member': 0.2, 'loyal': 0.25},
        'regular': {'base': 0.0, 'member': 0.1, 'loyal': 0.15}
    }
    discount = discounts[user_type]['base']
    if is_member:
        discount = discounts[user_type]['member']
    if years_active > 5:
        discount = discounts[user_type]['loyal']
    return price * (1 - discount)
